// La anti-repetición general (misma alerta en 10 min) la hace Enviar_Alerta.
// n8n devuelve un ítem vacío cuando la consulta no trae filas: se filtra por una columna clave.
// D7: posible exfiltración (> 1,000 filas por consulta en clientes o ventas). También valida el ataque A5.
const filas = $input.all().map(i => i.json).filter(r => r.queryid);
return filas.map(r => {
  const tablas = [...new Set((String(r.query).match(/\b(clientes|ventas)\b/gi) || []).map(t => t.toLowerCase()))];
  return { json: {
    codigo: 'D7',
    severidad: 'CRÍTICA',
    tipo: 'Posible exfiltración de datos (consulta masiva)',
    tabla: tablas.join(', ') || 'clientes / ventas',
    detalle: `Filas devueltas: ${r.filas_por_ejecucion} por consulta (umbral: 1000). Ejecuciones: ${r.calls}. queryid ${r.queryid}`,
    query: r.query,
    usuario: r.usuario,
    accion: `Revisar la actividad de ${r.usuario}. Si no es legítima: rotar su contraseña (scripts/rotar_password_bd.sh) y revocar acceso.`
  }};
});
